from numpy import array

def verif(ch):
    test=True
    #Lettres alpha maj
    i=0
    while test==True and i<len(ch):
        if not ("A"<=ch[i]<="Z"):
            test=False
        i=i+1 
    #Lettres Distincts
    for i in range(len(ch)-1):
        for j in range(i+1,len(ch)):
            if ch[i]==ch[j]:
                test=False

    #Long CH
    if not (5<=len(ch)<=10):
        test=False

    return test

def saisir():
    cle=input("Donner la Clé! : ")
    while not(verif(cle)):
        cle=input("Donner la Clé! : ")
    return cle

